using System.Net;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.TestHost;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using PersonalOrderDesk.Api;
using PersonalOrderDesk.Client;
using PersonalOrderDesk.Data;
using PersonalOrderDesk.Domain;
using PersonalOrderDesk.Services;
namespace PersonalOrderDesk.Tests;
public sealed class SyncApiTests : IAsyncLifetime
{
    private readonly string root=Path.Combine(Path.GetTempPath(),"Desk-sync-api-"+Guid.NewGuid().ToString("N"));
    private WebApplication app=null!;private HttpClient client=null!;private ServiceProvider mobile=null!;private SyncData baseline=null!;private ServerInfo info=null!;private Guid id;
    private string Pc=>Path.Combine(root,"pc","app.db");private string Phone=>Path.Combine(root,"phone","app.db");
    public async Task InitializeAsync(){Directory.CreateDirectory(Path.GetDirectoryName(Pc)!);Directory.CreateDirectory(Path.GetDirectoryName(Phone)!);var builder=WebApplication.CreateBuilder();builder.WebHost.UseTestServer();builder.Services.AddLocalWorkspace(Pc);builder.Services.AddDataProtection();builder.Services.AddSingleton(new NetworkAccessService(Path.GetDirectoryName(Pc)!,[]));builder.Services.AddSingleton(new ClientApiIdentity(Path.GetDirectoryName(Pc)!));builder.Services.AddSingleton<ClientApiSessions>();builder.Services.AddSingleton<SyncMergePlans>();builder.Services.ConfigureHttpJsonOptions(o=>o.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));app=builder.Build();await using(var scope=app.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<DeskDbContext>().Database.MigrateAsync();app.Use(async(c,next)=>{c.Connection.RemoteIpAddress=IPAddress.Loopback;await next(c);});app.UseMiddleware<ClientApiAccessMiddleware>();app.MapClientApi(Pc,Path.GetDirectoryName(Pc)!);app.MapSyncMerge(Pc,Path.GetDirectoryName(Pc)!);await app.StartAsync();client=app.GetTestClient();var login=await Post<SessionResponse>("api/v1/session",new SessionRequest(""));info=login.Server;client.DefaultRequestHeaders.Authorization=new("Bearer",login.Token);var item=await Post<WorkItemDetailDto>("api/v1/orders",new WorkItemSaveRequestDto(null,"API-SYNC","接口测试",ProjectType.Simulation,null,null,DateOnly.FromDateTime(DateTime.Today),DueDateMode.Auto,null,"起始进度","起始后续",10000,null,null));id=item.WorkItem.Id!.Value;var bytes=await client.GetByteArrayAsync("api/v1/snapshot");using var zip=new MemoryStream(bytes);using var db=new DeskDbContext(new DbContextOptionsBuilder<DeskDbContext>().UseSqlite("Data Source=:memory:").Options);await PortableSnapshot.ValidateAndWrite(zip,Phone,info.InstanceId,db.Database.GetMigrations().ToArray());baseline=await ThreeWaySync.Read(Phone);mobile=new ServiceCollection().AddLocalWorkspace(Phone).BuildServiceProvider();}
    private async Task<T> Post<T>(string path,object request){using var response=await client.PostAsJsonAsync(path,request,DeskJson.Options);response.EnsureSuccessStatusCode();return(await response.Content.ReadFromJsonAsync<T>(DeskJson.Options))!;}
    public async Task DisposeAsync(){client.Dispose();await app.DisposeAsync();await mobile.DisposeAsync();Directory.Delete(root,true);}
    private async Task<SyncReview> Prepare(Guid operation){await Post<SyncProtectionReceipt>("api/v1/sync/backup",new SyncProtectionRequest(operation));return await Post<SyncReview>("api/v1/sync/preview",new SyncMergeRequest(operation,info.InstanceId,baseline,await ThreeWaySync.Read(Phone)));}
    [Fact]public async Task Protected_merge_requires_choices_and_commits_once(){var p=(await client.GetFromJsonAsync<ClientOrder>($"api/v1/orders/{id}",DeskJson.Options))!.Detail.WorkItem;await Post<WorkItemDetailDto>($"api/v1/orders/{id}/progress",new UpdateProgressRequestDto(p.Version,"电脑内容",p.NextStep,null));var m=mobile.GetRequiredService<IWorkspaceGateway>();await m.Progress(id,new((await m.Editor(id)).Version,"手机内容","手机后续",null));var operation=Guid.NewGuid();var preview=await Prepare(operation);var conflict=Assert.Single(preview.Conflicts);using var rejected=await client.PostAsJsonAsync("api/v1/sync/commit",new SyncCommitRequest(operation,[],true),DeskJson.Options);Assert.Equal(HttpStatusCode.BadRequest,rejected.StatusCode);var request=new SyncCommitRequest(operation,new(){[conflict.Id]="phone"},true);Assert.True(await Post<bool>("api/v1/sync/commit",request));
        var plans=app.Services.GetRequiredService<SyncMergePlans>();var field=typeof(SyncMergePlans).GetField("plans",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!;((System.Collections.Concurrent.ConcurrentDictionary<Guid,SyncMergePlans.Plan>)field.GetValue(plans)!).Clear();
        Assert.True(await client.GetFromJsonAsync<bool>($"api/v1/sync/{operation}/status"));Assert.True(await Post<bool>("api/v1/sync/commit",request));
        using var changed=await client.PostAsJsonAsync("api/v1/sync/commit",new SyncCommitRequest(operation,new(){[conflict.Id]="pc"},true),DeskJson.Options);Assert.Equal(HttpStatusCode.BadRequest,changed.StatusCode);var result=(await client.GetFromJsonAsync<ClientOrder>($"api/v1/orders/{id}",DeskJson.Options))!.Detail.WorkItem;Assert.Equal("手机内容",result.CurrentWork);Assert.Equal("手机后续",result.NextStep);Assert.True(File.Exists(Path.Combine(root,"pc","Backups",$"sync-before-{operation:N}.db")));Assert.True(File.Exists(Path.Combine(root,"pc","Backups",$"sync-before-{operation:N}.result.json")));Assert.NotEmpty(await client.GetByteArrayAsync($"api/v1/sync/{operation}/backup"));}
    [Fact]public async Task Preview_without_pc_backup_or_wrong_instance_is_rejected(){var operation=Guid.NewGuid();using var missing=await client.PostAsJsonAsync("api/v1/sync/preview",new SyncMergeRequest(operation,info.InstanceId,baseline,baseline),DeskJson.Options);Assert.Equal(HttpStatusCode.BadRequest,missing.StatusCode);await Post<SyncProtectionReceipt>("api/v1/sync/backup",new SyncProtectionRequest(operation));using var wrong=await client.PostAsJsonAsync("api/v1/sync/preview",new SyncMergeRequest(operation,Guid.NewGuid().ToString("N"),baseline,baseline),DeskJson.Options);Assert.Equal(HttpStatusCode.BadRequest,wrong.StatusCode);}
    [Fact]public async Task Pc_change_after_backup_requires_a_new_protection_snapshot(){var operation=Guid.NewGuid();await Post<SyncProtectionReceipt>("api/v1/sync/backup",new SyncProtectionRequest(operation));var p=(await client.GetFromJsonAsync<ClientOrder>($"api/v1/orders/{id}",DeskJson.Options))!.Detail.WorkItem;await Post<WorkItemDetailDto>($"api/v1/orders/{id}/progress",new UpdateProgressRequestDto(p.Version,"备份后修改",null,null));using var rejected=await client.PostAsJsonAsync("api/v1/sync/preview",new SyncMergeRequest(operation,info.InstanceId,baseline,baseline),DeskJson.Options);Assert.Equal(HttpStatusCode.BadRequest,rejected.StatusCode);}
    [Fact]public async Task Unauthenticated_device_cannot_read_or_merge_sync_data(){client.DefaultRequestHeaders.Authorization=null;using var get=await client.GetAsync($"api/v1/sync/{Guid.NewGuid()}/backup");Assert.Equal(HttpStatusCode.Unauthorized,get.StatusCode);using var post=await client.PostAsJsonAsync("api/v1/sync/commit",new SyncCommitRequest(Guid.NewGuid(),[],true),DeskJson.Options);Assert.Equal(HttpStatusCode.Unauthorized,post.StatusCode);}
}
